/**
 * The reusable half of dustinedwards.info's header gate: what a response must carry, checked on the
 * response itself. A site runs it in CI against its own rendered responses (a Worker test, or the CLI
 * in bin/ against a preview or deployed origin).
 *
 * Every check names the failure it prevents (capsid/research/design-shared-functions.md, point 5):
 * sites sending no security headers at all, and report-only policies with no report sink, which enforce
 * nothing and tell nobody.
 */

import { CLOUDFLARE_WEB_ANALYTICS } from "./csp.mjs";
import { STANDARD_SECURITY_HEADERS } from "./headers.mjs";

/** @typedef {{ name: string, pass: boolean, detail: string }} CheckResult */

const ONE_YEAR = 31536000;
const STRICT_REFERRER = new Set(["no-referrer", "same-origin", "strict-origin", "strict-origin-when-cross-origin"]);

/**
 * @param {string} policy
 * @returns {Map<string, string[]>} directive name to its sources, lower-cased names
 */
export function parsePolicy(policy) {
  /** @type {Map<string, string[]>} */
  const out = new Map();
  for (const part of policy.split(";")) {
    const [name, ...sources] = part.trim().split(/\s+/);
    if (!name) continue;
    // The first occurrence wins, as browsers apply it.
    if (!out.has(name.toLowerCase())) out.set(name.toLowerCase(), sources);
  }
  return out;
}

/**
 * The features a Permissions-Policy denies outright (`feature=()`).
 *
 * @param {string} value
 */
function deniedFeatures(value) {
  return new Set([...value.matchAll(/([a-z-]+)=\(\s*\)/g)].map((m) => m[1]));
}

/**
 * @param {Headers} headers a real response's headers
 * @param {{ standard?: Readonly<Record<string, string>>, csp?: boolean, cloudflareWebAnalytics?: boolean }} [options]
 *   `standard`: the floor (default STANDARD_SECURITY_HEADERS; a site passes the set it declared). `csp`: grade the
 *   policy too; false for a response that carries none by design, such as a feed or an image.
 *   `cloudflareWebAnalytics`: the site is Cloudflare-proxied with Web Analytics on, so the policy must let the injected
 *   beacon run (its script path prefix) and report (connect-src with the site itself).
 * @returns {CheckResult[]}
 */
export function checkSecurityHeaders(headers, { standard = STANDARD_SECURITY_HEADERS, csp = true, cloudflareWebAnalytics = false } = {}) {
  /** @type {CheckResult[]} */
  const results = [];
  const result = (/** @type {string} */ name, /** @type {boolean} */ pass, /** @type {string} */ detail) =>
    results.push({ name, pass, detail });

  for (const [name, floor] of Object.entries(standard)) {
    const got = headers.get(name);
    if (got === null) {
      result(`${name} is present`, false, "ABSENT");
      continue;
    }
    if (name === "Strict-Transport-Security") {
      const age = Number(/max-age=(\d+)/i.exec(got)?.[1] ?? 0);
      const want = Number(/max-age=(\d+)/i.exec(floor)?.[1] ?? ONE_YEAR);
      result(`${name} lasts at least ${want} seconds`, age >= want, `got ${JSON.stringify(got)}`);
    } else if (name === "Referrer-Policy") {
      result(`${name} is a strict policy`, STRICT_REFERRER.has(got.trim().toLowerCase()), `got ${JSON.stringify(got)}`);
    } else if (name === "X-Frame-Options") {
      result(`${name} refuses framing`, /^(deny|sameorigin)$/i.test(got.trim()), `got ${JSON.stringify(got)}`);
    } else if (name === "Permissions-Policy") {
      const denied = deniedFeatures(got);
      const missing = [...deniedFeatures(floor)].filter((f) => !denied.has(f));
      result(`${name} denies ${[...deniedFeatures(floor)].join(", ")}`, missing.length === 0, missing.length ? `allows ${missing.join(", ")}; got ${JSON.stringify(got)}` : "");
    } else {
      result(`${name} is ${JSON.stringify(floor)}`, got.trim().toLowerCase() === floor.toLowerCase(), `got ${JSON.stringify(got)}`);
    }
  }

  if (!csp) return results;

  const enforced = headers.get("Content-Security-Policy");
  const reportOnly = headers.get("Content-Security-Policy-Report-Only");
  result(
    "the Content-Security-Policy is enforced, not only reported",
    Boolean(enforced),
    enforced ? "" : reportOnly ? "only a Report-Only policy is sent, which blocks nothing" : "ABSENT",
  );
  if (!enforced) return results;

  const policy = parsePolicy(enforced);
  const scripts = policy.get("script-src") ?? policy.get("default-src");
  result("the policy governs scripts (script-src or default-src)", Boolean(scripts), "neither directive is present, so any script runs");
  if (scripts) {
    result("scripts: no 'unsafe-inline'", !scripts.includes("'unsafe-inline'"), `script sources: ${scripts.join(" ")}`);
    result("scripts: no 'unsafe-eval'", !scripts.includes("'unsafe-eval'"), `script sources: ${scripts.join(" ")}`);
    const broad = scripts.filter((s) => s === "*" || /^(https?|data|blob):$/i.test(s));
    result("scripts: no wildcard or bare scheme source", broad.length === 0, broad.length ? `allows ${broad.join(" ")}` : "");
  }
  const objects = policy.get("object-src") ?? policy.get("default-src");
  result("object-src is 'none'", objects?.length === 1 && objects[0] === "'none'", `got ${objects ? objects.join(" ") : "ABSENT"}`);
  const base = policy.get("base-uri");
  result("base-uri is 'none' or 'self'", base?.length === 1 && (base[0] === "'none'" || base[0] === "'self'"), `got ${base ? base.join(" ") : "ABSENT (it does not fall back to default-src)"}`);
  result("frame-ancestors is set", policy.has("frame-ancestors"), "ABSENT (it does not fall back to default-src)");
  if (cloudflareWebAnalytics) {
    const missingScript = CLOUDFLARE_WEB_ANALYTICS.script.filter((source) => !(scripts ?? []).includes(source));
    const connect = policy.get("connect-src") ?? policy.get("default-src") ?? [];
    result(
      "the policy lets the Cloudflare Web Analytics beacon run: its script path prefix",
      missingScript.length === 0,
      `script-src lacks ${missingScript.join(" and ")}: the edge injects /beacon.min.js/v..., which the bare file URL does not match`,
    );
    result("the policy lets the beacon report: connect-src includes the site itself", connect.includes("'self'"), `connect-src is ${connect.join(" ") || "ABSENT"}`);
  }
  result(
    "violations are reported somewhere (report-uri or report-to)",
    policy.has("report-uri") || policy.has("report-to"),
    "no report sink: a blocked script is never heard about",
  );
  return results;
}

/**
 * @param {CheckResult[]} results
 * @returns {CheckResult[]}
 */
export const failures = (results) => results.filter((r) => !r.pass);

csp.mjs.source:
/**
 * Content-Security-Policy helpers: a per-request nonce, a hash source for an inline script, and the policy a site's
 * own list of what it loads builds.
 *
 * - generateNonce is foxhound's (app/lib/http/security-headers.ts): 16 random bytes, base64. Call it
 *   once per request and give the same value to the rendered <script nonce> and to the policy.
 * - scriptHash is dustinedwards.info's (workers/csp.mjs): Web Crypto rather than node:crypto, so a
 *   Worker and a Node gate run one function.
 * - buildContentSecurityPolicy takes the hosts a site loads, per kind, plus its nonce or hashes, and returns the
 *   header (enforced, or Report-Only so a repo can ship the policy before it blocks anything). It is the one place
 *   the policy's fixed parts (object-src, base-uri, frame-ancestors, form-action, the report sink) and the
 *   Cloudflare Web Analytics beacon are written.
 * - buildPolicy is the plain join, for a policy that is not a page's (a sandboxed media route).
 *
 * Which to use, nonce or hash: a response that is never shared-cached may carry a nonce. A response that is
 * edge-cached must not, since every reader would share one nonce for the cache lifetime; trust its inline scripts
 * by hash instead.
 */

/** @returns {string} a fresh nonce, 24 base64 characters */
export function generateNonce() {
  const bytes = crypto.getRandomValues(new Uint8Array(16));
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary);
}

/**
 * @param {string} text an inline script's exact text, as the page renders it
 * @returns {Promise<string>} `sha256-<base64>`, without the quotes the policy puts round it
 */
export async function scriptHash(text) {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
  return `sha256-${btoa(String.fromCharCode(...new Uint8Array(digest)))}`;
}

/**
 * The policy string from directives in the order given: `["default-src 'self'", "object-src 'none'"]`
 * becomes `default-src 'self'; object-src 'none'`. Order is kept, so a gate comparing strings sees
 * exactly what the site wrote.
 *
 * @param {readonly string[]} directives
 * @returns {string}
 */
export function buildPolicy(directives) {
  const empty = directives.filter((d) => d.trim() === "");
  if (empty.length > 0) throw new Error("a CSP directive is empty");
  return directives.join("; ");
}

/**
 * Cloudflare Web Analytics, automatic setup, written once for every site on a Cloudflare-proxied hostname. The edge
 * injects the beacon from a VERSIONED path (/beacon.min.js/v31..., measured in a browser), which the bare file URL
 * does not match; a source ending in "/" is a path prefix, so the second entry covers that one directory and nothing
 * else on the host. It reports to the site's own /cdn-cgi/rum, so connect-src needs 'self' on such a site (the
 * builder always includes it). The file is named, not hashed: its `integrity` changes whenever Cloudflare ships a
 * new beacon, and a pinned hash would block it within weeks.
 */
export const CLOUDFLARE_WEB_ANALYTICS = Object.freeze({
  script: Object.freeze([
    "https://static.cloudflareinsights.com/beacon.min.js",
    "https://static.cloudflareinsights.com/beacon.min.js/",
  ]),
});

/** A source expression as a policy writes it: no space, no semicolon, no comma. @param {string} source */
function checkSource(source) {
  if (typeof source !== "string" || source === "" || /[\s;,]/.test(source)) throw new Error(`${JSON.stringify(source)} is not a CSP source`);
  return source;
}

/**
 * @typedef {{
 *   script?: readonly string[],
 *   style?: readonly string[],
 *   img?: readonly string[],
 *   font?: readonly string[],
 *   connect?: readonly string[],
 *   frame?: readonly string[],
 *   media?: readonly string[],
 * }} CspSources
 *   The hosts (or schemes, such as `data:`) a site loads, per kind, beyond 'self'. A kind with nothing extra is
 *   omitted. A source is written as a policy writes it: `https://cdn.example.com`, `data:`.
 *
 * @typedef {{
 *   sources?: CspSources,
 *   scriptHashes?: readonly string[],
 *   styleHashes?: readonly string[],
 *   nonce?: string,
 *   styleAttributesInline?: boolean,
 *   cloudflareWebAnalytics?: boolean,
 *   reportUri?: string,
 *   reportTo?: string,
 *   reportOnly?: boolean,
 *   extraDirectives?: readonly string[],
 * }} SitePolicy
 *   `scriptHashes` / `styleHashes`: `sha256-...` values (scriptHash), for responses that may not carry a nonce.
 *   `nonce`: this request's nonce, for a response that is never shared-cached; it goes on script-src and style-src.
 *   `styleAttributesInline`: `style-src-attr 'unsafe-inline'`, for pages that emit style attributes, which a nonce
 *   cannot cover; the one inline allowance offered, scoped to attributes, which run no code.
 *   `reportUri` / `reportTo`: where violations go. A policy with no sink hides the page it breaks, so one is required.
 */

/**
 * The Content-Security-Policy header a site sends, from what it loads. The fixed parts are the same everywhere
 * (`default-src 'self'`, `object-src 'none'`, `base-uri 'none'`, `form-action 'self'`, `frame-ancestors 'none'`);
 * scripts are 'self', the site's hashes or nonce, its listed hosts and, when asked, the Cloudflare beacon. A script
 * source that is `*`, a bare scheme, 'unsafe-inline' or 'unsafe-eval' is refused here, so a site cannot list its way
 * to a policy the check would fail.
 *
 * @param {SitePolicy} site
 * @returns {{ name: "Content-Security-Policy" | "Content-Security-Policy-Report-Only", value: string }}
 */
export function buildContentSecurityPolicy(site) {
  const { sources = {}, scriptHashes = [], styleHashes = [], nonce, styleAttributesInline = false, cloudflareWebAnalytics = false, reportUri, reportTo, reportOnly = false, extraDirectives = [] } = site;
  if (!reportUri && !reportTo) throw new Error("a policy needs a report sink (reportUri or reportTo)");
  if (nonce !== undefined && !/^[A-Za-z0-9+/_-]{16,}={0,2}$/.test(nonce)) throw new Error("the nonce is not a base64 value of at least 16 characters");
  const hashSource = (/** @type {string} */ h) => {
    if (!/^sha(256|384|512)-[A-Za-z0-9+/_-]+={0,2}$/.test(h)) throw new Error(`${JSON.stringify(h)} is not a hash source`);
    return `'${h}'`;
  };
  const list = (/** @type {readonly string[] | undefined} */ hosts) => (hosts ?? []).map(checkSource);

  const scriptHosts = [...list(sources.script), ...(cloudflareWebAnalytics ? CLOUDFLARE_WEB_ANALYTICS.script : [])];
  for (const host of scriptHosts) {
    if (host === "*" || /^(https?|data|blob):$/i.test(host) || /^'unsafe-(inline|eval)'$/.test(host)) {
      throw new Error(`${host} is not an acceptable script source: name the host`);
    }
  }
  const nonceSource = nonce === undefined ? [] : [`'nonce-${nonce}'`];
  const directives = [
    "default-src 'self'",
    `script-src ${[...nonceSource, ...scriptHashes.map(hashSource), "'self'", ...scriptHosts].join(" ")}`,
    `style-src ${["'self'", ...nonceSource, ...styleHashes.map(hashSource), ...list(sources.style)].join(" ")}`,
    ...(styleAttributesInline ? ["style-src-attr 'unsafe-inline'"] : []),
    `font-src ${["'self'", ...list(sources.font)].join(" ")}`,
    `img-src ${["'self'", ...list(sources.img)].join(" ")}`,
    ...((sources.media ?? []).length > 0 ? [`media-src ${["'self'", ...list(sources.media)].join(" ")}`] : []),
    // 'self' is always present: the Cloudflare beacon reports to /cdn-cgi/rum on the site's own origin.
    `connect-src ${["'self'", ...list(sources.connect)].join(" ")}`,
    ...((sources.frame ?? []).length > 0 ? [`frame-src ${["'self'", ...list(sources.frame)].join(" ")}`] : []),
    "object-src 'none'",
    "base-uri 'none'",
    "form-action 'self'",
    "frame-ancestors 'none'",
    ...extraDirectives,
    ...(reportUri ? [`report-uri ${checkSource(reportUri)}`] : []),
    ...(reportTo ? [`report-to ${checkSource(reportTo)}`] : []),
  ];
  return { name: reportOnly ? "Content-Security-Policy-Report-Only" : "Content-Security-Policy", value: buildPolicy(directives) };
}

headers.mjs.source:
/**
 * The standard response header set every site in the portfolio sends, and one way to apply a set.
 *
 * The values are the OWASP Secure Headers Project's own, read by update-owasp.mjs (owasp-headers.mjs says when and
 * from where), for every header that is the same everywhere. Four of OSHP's recommendations are not in the standard,
 * each for a reason that is written down next to it (OWASP_SKIPPED); a site that must differ on another header says
 * so, with a reason, in `overrides`, and the check holds the site to the set it declared.
 *
 * What a site adds on top (a Permissions-Policy of its own, say) is its own and is stated as an override or an
 * extra, never as a copy of this set.
 */

import { OWASP_RECOMMENDED } from "./owasp-headers.mjs";

/**
 * The OSHP recommendations this package does not put in the standard set, and why. Each would break a normal site if
 * sent on every response, or is not one value for every site.
 *
 * @type {Readonly<Record<string, string>>}
 */
export const OWASP_SKIPPED = Object.freeze({
  "Cache-Control": "OSHP's `no-store, max-age=0` on every response makes nothing cacheable, edge caches included; a site sets caching per route.",
  "Clear-Site-Data":
    "On every response it wipes the reader's cookies, storage and cache at each page load, which logs everyone out of everything; OSHP's own suite tests it on the logout page only, so it is exported as LOGOUT_HEADERS for a site's logout response.",
  "Cross-Origin-Embedder-Policy":
    "`require-corp` refuses every cross-origin subresource that does not opt in with Cross-Origin-Resource-Policy or CORS, which breaks images, fonts and scripts a normal site loads from elsewhere; a site turns it on only when it needs cross-origin isolation.",
  "Content-Security-Policy":
    "A policy is not one string for every site: it names what that site loads, so the package builds it from the site's own list (buildContentSecurityPolicy) instead of sharing OSHP's `default-src 'self'` example.",
});

/**
 * The standard set: OSHP's recommendations minus OWASP_SKIPPED, in OSHP's words.
 *
 * @type {Readonly<Record<string, string>>}
 */
export const STANDARD_SECURITY_HEADERS = Object.freeze(
  Object.fromEntries(Object.entries(OWASP_RECOMMENDED).filter(([name]) => !(name in OWASP_SKIPPED))),
);

/**
 * The headers OSHP recommends for a logout response only (Clear-Site-Data), for a site that has one.
 *
 * @type {Readonly<Record<string, string>>}
 */
export const LOGOUT_HEADERS = Object.freeze({ "Clear-Site-Data": OWASP_RECOMMENDED["Clear-Site-Data"] ?? "" });

/**
 * @typedef {{ value: string | null, reason: string }} HeaderOverride
 *   A header a site sends differently from the standard: its own value, or null to send none, and why. A reason is
 *   required, so a deviation is a decision someone wrote down and not an accident.
 */

/**
 * The set a site sends: the standard with the site's overrides applied. An override must carry a reason and must
 * change something; one that says what the standard already says is refused, so the list stays the list of real
 * deviations.
 *
 * @param {{ overrides?: Readonly<Record<string, HeaderOverride>> }} [site]
 * @returns {Record<string, string>}
 */
export function buildSecurityHeaders({ overrides = {} } = {}) {
  /** @type {Record<string, string>} */
  const set = { ...STANDARD_SECURITY_HEADERS };
  for (const [name, { value, reason }] of Object.entries(overrides)) {
    if (typeof reason !== "string" || reason.trim().length < 12) throw new Error(`the override of ${name} gives no reason`);
    if (value === (STANDARD_SECURITY_HEADERS[name] ?? undefined)) throw new Error(`the override of ${name} says what the standard already says`);
    if (value === null) {
      if (!(name in set)) throw new Error(`the override of ${name} removes a header the standard does not send`);
      delete set[name];
    } else if (value.trim() === "") {
      throw new Error(`the override of ${name} is empty; use null to send none`);
    } else {
      set[name] = value;
    }
  }
  return set;
}

/**
 * Stamps a header set onto `headers` in place.
 *
 * `overwrite: true` (the default) makes the set authoritative, which is what dustinedwards.info does on
 * every exit. `overwrite: false` keeps any value a route already chose, which is foxhound's merge. A
 * Response whose headers are immutable (Response.redirect, the Cache API) throws on `set`; rebuild it
 * with `new Response(res.body, { ...res, headers: new Headers(res.headers) })` and apply to that.
 *
 * @param {Headers} headers
 * @param {Readonly<Record<string, string>>} [set]
 * @param {{ overwrite?: boolean }} [options]
 */
export function applyHeaderSet(headers, set = STANDARD_SECURITY_HEADERS, { overwrite = true } = {}) {
  for (const [name, value] of Object.entries(set)) {
    if (overwrite || !headers.has(name)) headers.set(name, value);
  }
}

oshp-suite.mjs.source:
/**
 * Runs OWASP's own header test suite against a response, with no network and no venom.
 *
 * The suite is the OWASP Secure Headers Project's validator (oshp-tests-suite.yml, read verbatim by update-owasp.mjs
 * from subprojects/validator/tests_suite.yml). It is a venom test plan: each test case GETs the target and asserts on
 * `result.statuscode` and `result.headers.<Name>`. Venom is a Go binary that needs a live URL; this runs the same
 * assertions on the headers a site's code would send, so CI proves a policy before it is deployed. Only the operators
 * the suite uses are implemented, and any other one throws, so a changed suite fails loudly instead of passing quietly.
 *
 * The suite is the oracle for OSHP's recommendation, and OSHP's recommendation includes headers this package
 * deliberately does not send everywhere (OWASP_SKIPPED), so a run is expected to fail exactly those test cases.
 * Pass the YAML already parsed (a plain object), so this module needs no YAML parser.
 */

/** @typedef {{ status: number, headers: Headers }} SuiteResponse */

/** @param {string} text the assertion's argument text @returns {string[]} */
function argumentsOf(text) {
  return [...text.matchAll(/"([^"]*)"|'([^']*)'|(\S+)/g)].map((m) => m[1] ?? m[2] ?? m[3] ?? "");
}

/**
 * @param {string} assertion e.g. `result.headers.X-Frame-Options ShouldBeIn "deny" "DENY"`
 * @param {SuiteResponse} response
 * @returns {boolean}
 */
function holds(assertion, response) {
  const match = /^(result\.statuscode|result\.headers\.[A-Za-z0-9-]+)\s+(Should[A-Za-z]+)\s*(.*)$/.exec(assertion.trim());
  if (!match) throw new Error(`unsupported assertion: ${assertion}`);
  const [, subject = "", operator = "", rest = ""] = match;
  const value =
    subject === "result.statuscode" ? String(response.status) : (response.headers.get(subject.slice("result.headers.".length)) ?? null);
  const args = argumentsOf(rest);
  switch (operator) {
    case "ShouldEqual":
      return value !== null && value === args[0];
    case "ShouldNotBeNil":
      return value !== null;
    case "ShouldBeNil":
      return value === null;
    case "ShouldBeIn":
      return value !== null && args.includes(value);
    case "ShouldContainSubstring":
      return value !== null && value.includes(args[0] ?? "");
    case "ShouldNotContainSubstring":
      return value !== null && !value.includes(args[0] ?? "");
    default:
      throw new Error(`unsupported operator ${operator} in: ${assertion}`);
  }
}

/** @param {unknown} assertion @param {SuiteResponse} response @returns {boolean} */
function holdsAny(assertion, response) {
  if (typeof assertion === "string") return holds(assertion, response);
  if (assertion && typeof assertion === "object" && Array.isArray(/** @type {any} */ (assertion).or)) {
    return /** @type {any} */ (assertion).or.some((/** @type {unknown} */ a) => holdsAny(a, response));
  }
  throw new Error(`unsupported assertion shape: ${JSON.stringify(assertion)}`);
}

/**
 * Runs every test case of the suite.
 *
 * @param {{ testcases: Array<{ name: string, steps: Array<{ url?: string, assertions?: unknown[] }> }> }} suite the parsed suite
 * @param {{ page: SuiteResponse, logout?: SuiteResponse }} responses the page the suite calls `target_site`, and the
 *   logout response it calls `target_site/logout_url` (cases that need it fail when none is given)
 * @returns {Array<{ name: string, pass: boolean, failed: string[] }>}
 */
export function runOshpSuite(suite, responses) {
  if (!Array.isArray(suite?.testcases) || suite.testcases.length === 0) throw new Error("the suite has no test cases");
  return suite.testcases.map((testcase) => {
    /** @type {string[]} */
    const failed = [];
    for (const step of testcase.steps) {
      const response = String(step.url ?? "").includes("logout_url") ? responses.logout : responses.page;
      for (const assertion of step.assertions ?? []) {
        if (!response) {
          failed.push(typeof assertion === "string" ? assertion : JSON.stringify(assertion));
        } else if (!holdsAny(assertion, response)) {
          failed.push(typeof assertion === "string" ? assertion : JSON.stringify(assertion));
        }
      }
    }
    return { name: testcase.name, pass: failed.length === 0, failed };
  });
}

update-owasp.mjs.source:
#!/usr/bin/env node
/**
 * Refreshes the package's copy of the OWASP Secure Headers Project data from the project itself, so no default is
 * typed from memory:
 *
 *   node update-owasp.mjs
 *
 * It reads, from the project's repository (https://github.com/OWASP/www-project-secure-headers, the source of
 * https://owasp.org/www-project-secure-headers/):
 *   - ci/headers_add.json     the headers OSHP recommends a response carry, with its `last_update_utc`
 *   - ci/headers_remove.json  the headers OSHP recommends a response not carry
 *   - subprojects/validator/tests_suite.yml  OSHP's own header test suite (a venom suite), kept verbatim
 *
 * and writes owasp-headers.mjs and oshp-tests-suite.yml beside this file, and the "Source" block of README.md with
 * the page, the files and the date they were read. Exits non-zero when a file cannot be read or has an unexpected
 * shape, so a failed refresh never leaves a half-written set.
 */

import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

const RAW = "https://raw.githubusercontent.com/OWASP/www-project-secure-headers/master";
const PAGE = "https://owasp.org/www-project-secure-headers/";
const REPO = "https://github.com/OWASP/www-project-secure-headers";
const here = (/** @type {string} */ name) => fileURLToPath(new URL(name, import.meta.url));

/** @param {string} path */
async function read(path) {
  const res = await fetch(`${RAW}/${path}`, { headers: { "user-agent": "security-headers update" } });
  if (!res.ok) throw new Error(`${RAW}/${path} answered ${res.status}`);
  return res.text();
}

const [addText, removeText, suite] = await Promise.all([
  read("ci/headers_add.json"),
  read("ci/headers_remove.json"),
  read("subprojects/validator/tests_suite.yml"),
]);
const add = JSON.parse(addText);
const remove = JSON.parse(removeText);
if (!Array.isArray(add.headers) || add.headers.length === 0 || add.headers.some((/** @type {any} */ h) => typeof h?.name !== "string" || typeof h?.value !== "string")) {
  throw new Error("headers_add.json is not a list of { name, value }");
}
if (!Array.isArray(remove.headers) || remove.headers.some((/** @type {any} */ h) => typeof h !== "string")) throw new Error("headers_remove.json is not a list of names");
if (!suite.includes("testcases:")) throw new Error("tests_suite.yml has no testcases");

const fetchedAt = new Date().toISOString().slice(0, 10);
const headers = Object.fromEntries(add.headers.map((/** @type {{ name: string, value: string }} */ h) => [h.name, h.value]));

const module = `// GENERATED by update-owasp.mjs from the OWASP Secure Headers Project. Do not edit: run the script.
// Page: ${PAGE}
// Data: ${REPO}/tree/master/ci (headers_add.json, headers_remove.json), read ${fetchedAt}.

/** Where these values were read, and when. */
export const OWASP_SOURCE = Object.freeze({
  page: ${JSON.stringify(PAGE)},
  data: ${JSON.stringify(`${REPO}/tree/master/ci`)},
  readOn: ${JSON.stringify(fetchedAt)},
  lastUpdateUtc: ${JSON.stringify(add.last_update_utc ?? null)},
});

/** The headers OSHP recommends a response carry, as OSHP writes them. */
export const OWASP_RECOMMENDED = Object.freeze(${JSON.stringify(headers, null, 2)});

/** The headers OSHP recommends a response not carry (they name the software that served it). */
export const OWASP_REMOVE = Object.freeze(${JSON.stringify(remove.headers, null, 2)});
`;
await writeFile(here("owasp-headers.mjs"), module, "utf8");
await writeFile(here("oshp-tests-suite.yml"), suite, "utf8");

const block = [
  "<!-- owasp:begin -->",
  `The defaults are read from the OWASP Secure Headers Project, not typed here: page ${PAGE}, data ${REPO}/tree/master/ci`,
  `(\`headers_add.json\`, \`headers_remove.json\`, last updated by OWASP ${add.last_update_utc ?? "(not stated)"} UTC), and its header test suite`,
  `\`subprojects/validator/tests_suite.yml\`, all read on **${fetchedAt}**. Refresh with \`node update-owasp.mjs\`.`,
  "<!-- owasp:end -->",
].join("\n");
const readmePath = here("README.md");
const readme = await readFile(readmePath, "utf8");
if (!readme.includes("<!-- owasp:begin -->")) throw new Error("README.md has no owasp:begin marker");
await writeFile(readmePath, readme.replace(/<!-- owasp:begin -->[\s\S]*?<!-- owasp:end -->/, block), "utf8");
console.log(`read ${Object.keys(headers).length} recommended headers, ${remove.headers.length} to remove, and the suite, on ${fetchedAt}`);
